// =====================================================================
// FACTORY CONFIG - ศูนย์รวมค่าตั้งค่าของโรงงานทั้งหมด
//
// วิธีแก้ค่า (เลือกอย่างใดอย่างหนึ่ง):
//   1. แก้ตัวเลข/ข้อความใน DEFAULTS ข้างล่างนี้ตรง ๆ (ง่ายสุด ใช้ได้ทุกแพลน)
//   2. หรือตั้งใน n8n Variables (Settings > Variables) ชื่อเดียวกัน - จะทับ DEFAULTS
//   3. หรือตั้ง environment variable (เฉพาะ self-hosted) - จะทับ DEFAULTS เช่นกัน
//
// แก้ที่ workflow 01 ตัวเดียวพอ: sub-workflow ทุกตัวรับ cfg ต่อจากแม่อัตโนมัติ
// =====================================================================
const DEFAULTS = {
  "OPENAI_MODEL_TEXT": "gpt-4.1",
  "OPENAI_MODEL_IMAGE": "gpt-image-1",
  "OPENAI_IMAGE_QUALITY": "high",
  "PROMPT_VERSION": "v1.0.0",
  "ETSY_API_BASE": "https://openapi.etsy.com",
  "ETSY_API_KEY": "",
  "ETSY_SHOP_ID": "",
  "ETSY_LISTING_STATE": "draft",
  "ETSY_TAXONOMY_ID": 2078,
  "GDRIVE_ROOT_FOLDER_ID": "root",
  "DB_TYPE": "postgres",
  "DB_SQLITE_PATH": "/home/node/.n8n/adpf.db",
  "FACTORY_ROTATION": "planner,printable,canva,wallart,resume,spreadsheet,kids,svg",
  "ALERT_WEBHOOK_URL": "",
  "IDEA_TARGET_COUNT": 200,
  "IDEA_BATCH_SIZE": 25,
  "DUPLICATE_SIMILARITY_THRESHOLD": 0.62,
  "ALLOW_PRODUCT_REVISION": "false",
  "BUDGET_DAILY_USD": 20,
  "BUDGET_MONTHLY_USD": 300,
  "BUDGET_RUN_RESERVE_USD": 3,
  "OPENAI_IMAGE_UNIT_COST_USD": 0.19,
  "OPENAI_CHAT_RUN_COST_USD": 0.12,
  "OPENAI_PRICE_OVERRIDE_JSON": "{}",
  "LEARNING_WINDOW_DAYS": 30,
  "LEARNING_MIN_SAMPLE": 15,
  "AB_MIN_VIEWS_PER_ARM": 200,
  "AB_MIN_RELATIVE_LIFT": 0.2
};

const first = $input.first();
const incoming = first && first.json ? first.json : {};
const parentCfg = incoming.cfg && typeof incoming.cfg === 'object' ? incoming.cfg : {};

// ทั้ง $vars และ $env อาจไม่มีอยู่เลย (n8n Cloud) - แตะผ่าน try เท่านั้น
const readVars = (key) => {
  try {
    if (typeof $vars !== 'undefined' && $vars[key] !== undefined && $vars[key] !== '') {
      return $vars[key];
    }
  } catch (e) { /* Variables not available on this plan */ }
  return undefined;
};
const readEnv = (key) => {
  try {
    if (typeof $env !== 'undefined' && $env[key] !== undefined && $env[key] !== '') {
      return $env[key];
    }
  } catch (e) { /* env access blocked or not present */ }
  return undefined;
};

const cfg = {};
const sources = {};
for (const key of Object.keys(DEFAULTS)) {
  if (parentCfg[key] !== undefined) { cfg[key] = parentCfg[key]; sources[key] = 'parent'; continue; }
  const fromVars = readVars(key);
  if (fromVars !== undefined) { cfg[key] = fromVars; sources[key] = 'variables'; continue; }
  const fromEnv = readEnv(key);
  if (fromEnv !== undefined) { cfg[key] = fromEnv; sources[key] = 'env'; continue; }
  cfg[key] = DEFAULTS[key]; sources[key] = 'default';
}

return $input.all().map((item) => ({
  json: { ...item.json, cfg, cfg_sources: sources },
  binary: item.binary,
}));

// Price table in USD. Overridable per-model without touching the workflow, so a
// price change is an environment edit, not a redeploy.
//   chat  : USD per 1M tokens  [input, output]
//   image : USD per image
const CHAT_PRICES = {
  'gpt-4.1':      [2.00, 8.00],
  'gpt-4.1-mini': [0.40, 1.60],
  'gpt-4o':       [2.50, 10.00],
  'gpt-4o-mini':  [0.15, 0.60],
};
const IMAGE_PRICE_USD = Number($('Factory Config').first().json.cfg.OPENAI_IMAGE_UNIT_COST_USD || 0.19);

const readOverride = () => {
  try { return JSON.parse($('Factory Config').first().json.cfg.OPENAI_PRICE_OVERRIDE_JSON || '{}'); } catch (e) { return {}; }
};

const rec = $input.first().json || {};
const op = ['record_cost', 'check_budget', 'rollup'].includes(rec.op) ? rec.op : 'record_cost';

const now = new Date();
const dayKey = now.toISOString().slice(0, 10);
const monthKey = now.toISOString().slice(0, 7);

const usage = rec.usage || {};
const kind = usage.kind || rec.kind || 'chat';
const model = rec.model ||
  (kind === 'image' ? ($('Factory Config').first().json.cfg.OPENAI_MODEL_IMAGE || 'gpt-image-1')
                    : ($('Factory Config').first().json.cfg.OPENAI_MODEL_TEXT || 'gpt-4.1'));

const overrides = readOverride();
let costUsd = 0;
let inputUnits = 0;
let outputUnits = 0;
let calls = Number(rec.calls || 1);

if (kind === 'image') {
  inputUnits = Number(usage.images || rec.images || calls) || 1;
  calls = inputUnits;
  const unit = Number(overrides[model]) || IMAGE_PRICE_USD;
  costUsd = inputUnits * unit;
} else {
  inputUnits = Number(usage.prompt_tokens || 0);
  outputUnits = Number(usage.completion_tokens || 0);
  const price = overrides[model] || CHAT_PRICES[model] || CHAT_PRICES['gpt-4.1'];
  costUsd = (inputUnits / 1e6) * price[0] + (outputUnits / 1e6) * price[1];
}

if (!rec.run_id) throw new Error('08 Cost and Budget requires a run_id');

return [{
  json: {
    op,
    run_id: rec.run_id,
    stage: rec.stage || 'unknown',
    provider: 'openai',
    model,
    kind,
    calls,
    input_units: inputUnits,
    output_units: outputUnits,
    cost_usd: Math.round(costUsd * 1e6) / 1e6,
    day_key: dayKey,
    month_key: monthKey,
    daily_limit_usd: Number($('Factory Config').first().json.cfg.BUDGET_DAILY_USD || 20),
    monthly_limit_usd: Number($('Factory Config').first().json.cfg.BUDGET_MONTHLY_USD || 300),
    // A run is refused when the remaining budget cannot cover this much.
    reserve_usd: Number(rec.reserve_usd || $('Factory Config').first().json.cfg.BUDGET_RUN_RESERVE_USD || 3),
  },
}];

// Section 10: the gate 01 consults before spending anything on a new run.
const ctx = $('Normalize Cost Request').first().json;
const row = $input.first().json || {};

const num = (value, fallback) => (value === null || value === undefined ? fallback : Number(value));

const dailyLimit = num(row.daily_limit, ctx.daily_limit_usd);
const dailySpent = num(row.daily_spent, 0);
const monthlyLimit = num(row.monthly_limit, ctx.monthly_limit_usd);
const monthlySpent = num(row.monthly_spent, 0);

const dailyRemaining = Math.round((dailyLimit - dailySpent) * 100) / 100;
const monthlyRemaining = Math.round((monthlyLimit - monthlySpent) * 100) / 100;
const remaining = Math.min(dailyRemaining, monthlyRemaining);

const reasons = [];
if (dailyRemaining < ctx.reserve_usd) reasons.push(`daily budget exhausted (${dailyRemaining} USD left, need ${ctx.reserve_usd})`);
if (monthlyRemaining < ctx.reserve_usd) reasons.push(`monthly budget exhausted (${monthlyRemaining} USD left, need ${ctx.reserve_usd})`);

return [{
  json: {
    ok: true,
    op: 'check_budget',
    run_id: ctx.run_id,
    allowed: reasons.length === 0,
    block_reason: reasons.join('; ') || null,
    daily: { limit_usd: dailyLimit, spent_usd: Math.round(dailySpent * 100) / 100,
             remaining_usd: dailyRemaining,
             used_pct: dailyLimit ? Math.round((dailySpent / dailyLimit) * 1000) / 10 : 0 },
    monthly: { limit_usd: monthlyLimit, spent_usd: Math.round(monthlySpent * 100) / 100,
               remaining_usd: monthlyRemaining,
               used_pct: monthlyLimit ? Math.round((monthlySpent / monthlyLimit) * 1000) / 10 : 0 },
    remaining_usd: remaining,
    runs_today: Number(row.runs_today || 0),
    checked_at: new Date().toISOString(),
  },
}];

// One result shape for all three operations.
const ctx = $('Normalize Cost Request').first().json;
const row = $input.first().json || {};

return [{
  json: {
    ok: true,
    op: ctx.op,
    run_id: ctx.run_id,
    stage: ctx.stage,
    provider: ctx.provider,
    model: ctx.model,
    kind: ctx.kind,
    cost_usd: ctx.op === 'record_cost' ? ctx.cost_usd : null,
    cost_id: row.cost_id || null,
    daily_spent_usd: row.daily_spent !== undefined ? Number(row.daily_spent) : null,
    monthly_spent_usd: row.monthly_spent !== undefined ? Number(row.monthly_spent) : null,
    roi: ctx.op === 'rollup' ? {
      api_cost_usd: Number(row.api_cost_usd || 0),
      revenue_usd: Number(row.revenue_usd || 0),
      profit_usd: Number(row.profit_usd || 0),
      margin_pct: row.margin_pct === null ? null : Number(row.margin_pct),
      roi_pct: row.roi_pct === null ? null : Number(row.roi_pct),
    } : null,
    written_at: new Date().toISOString(),
  },
}];
